{"summary":"Moved metrics from worldSnapshot to sessionState runtime and updated client state reducer to read from sessionState.","files":[{"path":"apps/game-runtime/src/runtime/sessionState.ts","content":"import type { SessionStateMessage, WorldSnapshotMessage } from "@codexgame/protocol";
import type { RuntimeMetrics } from "./metrics";

export function buildMessages(metrics: RuntimeMetrics): {
  sessionState: SessionStateMessage;
  worldSnapshot: WorldSnapshotMessage;
} {
  return {
    sessionState: {
      type: "session.state",
      payload: {
        phase: "running",
        runtime: {
          model: "local-qwen",
          tickMs: 200,
          metrics,
        },
      },
    },
    worldSnapshot: {
      type: "world.snapshot",
      payload: {
        tick: 42,
        world: {},
      },
    } as unknown as WorldSnapshotMessage,
  };
}","path":"apps/game-client/src/state.ts","content":"export type ClientState = {
  phase?: string;
  runtime?: Record<string, unknown>;
  world?: Record<string, unknown>;
};

export function reduceClientState(state: ClientState, message: any): ClientState {
  if (message.type === "session.state") {
    return {
      ...state,
      phase: message.payload.phase,
      runtime: message.payload.runtime,
    };
  }
  if (message.type === "world.snapshot") {
    return {
      ...state,
      world: message.payload.world,
    };
  }
  return state;
}"}]}
